import json, sys
baseline = json.load(open('baseline-packages.json'))
after = json.loads(sys.stdin.read())

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)
if b == a:
    print('MATCH: All package versions identical before and after conversion.')
else:
    for k in sorted(set(list(b.keys()) + list(a.keys()))):
        bv = b.get(k, 'MISSING')
        av = a.get(k, 'MISSING')
        if bv != av:
            print(f'DIFF: {k[0]} {k[1]}: {bv} -> {av}')
"

